#!/usr/bin/env node
/**
 * Build an `all.js` from the golden oracle with ghcts's RTS in place of GHC's.
 *
 * The oracle (references/miso-lynx/oracle-jsexe) is real GHC 9.12.2 output for
 * the miso counter: rts.js + lib.js + out.js + runmain.js concatenated. Only
 * the first of those is generated by GHC.StgToJS.Rts.Rts, which is what
 * src/stg-js/rts.ts reproduces. Swapping just that one file and running the
 * result is the sharpest test our RTS can face: the program driving it is real
 * compiled Haskell that expects GHC's exact calling convention, so anything we
 * got wrong shows up as a crash rather than a passing unit test.
 *
 *   node scripts/rts-swap.mjs               # write the swapped bundle
 *   node scripts/rts-swap.mjs --oracle      # write the unmodified oracle, as a control
 *   node scripts/rts-swap.mjs --check       # report undefined symbols, write nothing
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ORACLE = "references/miso-lynx/oracle-jsexe";
const OUT = "dist/rts-swap";
const args = process.argv.slice(2);
const useOracleRts = args.includes("--oracle");

const part = (n) => readFileSync(join(ORACLE, n), "utf8");
const { renderRts } = await import("../dist/stg-js/rts.js");

const rts = useOracleRts ? part("rts.js") : renderRts();
const lib = part("lib.js");
const out = part("out.js");
const runmain = part("runmain.js");

/** Symbols a chunk defines at the top level. */
function defined(source) {
  const names = new Set();
  for (const m of source.matchAll(/^(?:function|var)\s+(h\$[A-Za-z0-9_$]+)/gm)) names.add(m[1]);
  return names;
}

// What matters is not an absolute symbol audit - `defined()` misses the many
// shapes GHC's hand-written lib.js uses (conditional assignment, indented
// declarations, constants poked in by h$processConstants) and so reports
// ~99 false positives even for the untouched oracle. What matters is the
// DIFFERENCE: every symbol GHC's rts.js defines, ours must define too.
const ourSymbols = defined(rts);
const oracleSymbols = defined(part("rts.js"));
const referenced = new Set([...(lib + out).matchAll(/h\$[A-Za-z0-9_$]+/g)].map((m) => m[0]));
const needed = [...oracleSymbols].filter((n) => referenced.has(n));
const missing = needed.filter((n) => !ourSymbols.has(n)).sort();

console.log(`rts: ${useOracleRts ? "oracle" : "ghcts"}  ${(rts.length / 1024).toFixed(0)}KB, ${ourSymbols.size} symbols`);
console.log(`the program needs ${needed.length} of GHC's rts.js symbols; ${missing.length} missing`);
if (missing.length) console.log(`  ${missing.join(" ")}`);

if (args.includes("--check")) process.exit(missing.length ? 1 : 0);

// --stub-missing answers a different question than --check: of the symbols we
// have not ported yet, which does the counter actually *call*? A stub that
// throws its own name turns "the bundle will not load" into "here is the one
// function that mattered", and proves whether the unported set is the only
// thing left or merely the first thing.
const stubs = args.includes("--stub-missing")
  ? missing.map((n) => `function ${n}(){ throw new Error("STUB ${n}"); }\n`).join("")
  : "";
if (stubs) console.log(`stubbing ${missing.length} unported symbols`);

mkdirSync(OUT, { recursive: true });
const all = rts + stubs + lib + out + runmain;
const file = join(OUT, "all.js");
writeFileSync(file, all);
console.log(`\nwrote ${file}  (${(all.length / 1024 / 1024).toFixed(2)}MB)`);
console.log(`pack it with:\n  node scripts/pack-lynx.mjs --js ${file} --out dist/rts-swap/lynx`);
